INSERT INTO `farms` VALUES (1,'Kamadhenu Anglo-nubian Goats','<p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"font-weight: bold; color: rgb(0, 51, 0); font-size: small;\">Племенной репродуктор по разведению коз Англо-нубийской породы</span></p><p style=\"text-align: center;\"><font color=\"#003300\" face=\"Arial, Verdana\"><b style=\"font-size: small;\">Member of the British goat society</b></font></p><p style=\"text-align: center;\"><font color=\"#003300\" face=\"Arial, Verdana\"><b style=\"font-size: small;\">Member of the Association of Breeding Goats</b></font></p><p style=\"text-align: center;\"><font color=\"#003300\" face=\"Arial, Verdana\"><b style=\"font-size: small;\"><br></b></font></p><p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"color: rgb(0, 51, 0); font-size: small;\">Основным направлением деятельности<span style=\"font-style: italic;\"> <strong style=\"\">ФХ \"Камадхену Англо-нубийские Козы\"</strong> </span>является чистопородное разведение коз англо-нубийской породы.</span></p><p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"color: rgb(0, 51, 0); font-size: small;\"><br></span></p>\r\n	                    <p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"color: rgb(0, 51, 0); font-size: small;\">Фермерское хозяйство расположено в 80 км от Киева по Житомирской трассе.</span></p>\r\n	    	            <p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"color: rgb(0, 51, 0); font-size: small;\"><strong style=\"font-style: normal; font-weight: normal;\">Владелец ФХ:</strong><span style=\"font-weight: bold; font-style: italic;\"> Алексеева Марина</span></span></p>\r\n	                    <p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><strong style=\"color: rgb(0, 51, 0); font-size: small;\">Обратная связь:</strong></p>\r\n	                    <p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"color: rgb(0, 51, 0); font-size: small;\">+380 50 312 58 68</span></p>\r\n	                    <p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"font-family: Arial, sans-serif; white-space: nowrap; color: rgb(0, 51, 0); font-size: small;\">anglonubiergoats@gmail.com</span></p>\r\n	                    <p style=\"font-family: Arial, Verdana; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal; text-align: center;\"><span style=\"font-family: Arial, sans-serif; white-space: nowrap; color: rgb(0, 51, 0); font-size: small;\"><strong style=\"\">Скайп:</strong> a-26-z</span></p>','farm_1512944214.jpg','1082574__pierced-goat_p.jpg'),(3,'Элика','<div style=\"font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal;\"><span style=\"color: rgb(51, 51, 51); font-family: \" lucida=\"\" grande\",=\"\" \"trebuchet=\"\" ms\",=\"\" verdana,=\"\" helvetica,=\"\" arial,=\"\" sans-serif;=\"\" font-size:=\"\" 15.6px;=\"\" background-color:=\"\" rgba(254,=\"\" 254,=\"\" 244,=\"\" 0.4);\"=\"\"><br></span></div><span style=\"\" lucida=\