DROP TABLE IF EXISTS `goats_born`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `goats_born` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_goat` int(11) NOT NULL COMMENT 'ID матери',
  `id_child` int(11) NOT NULL COMMENT 'ID ребенка',
  `par_1` float DEFAULT NULL COMMENT 'Оценочный балл каждого козлёнка',
  `par_2` int(1) DEFAULT NULL COMMENT 'Роды (нормальные/патологические)',
  `par_3` int(1) DEFAULT NULL COMMENT 'Отделение последа (самостоятельное/ручное)',
  `par_4` int(4) DEFAULT NULL COMMENT 'Послед отделился через (время в минутах или часах)',
  `par_5` int(1) DEFAULT NULL COMMENT 'Выкармливание козлят (на подсосе/на выпойке)',
  `par_6` float DEFAULT NULL COMMENT 'Молозива выдоено (в кг)',
  `special` text COMMENT 'Особые отметки',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='Информация по новорожденным';
