DROP TABLE IF EXISTS `goats_data`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `goats_data` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_goat` int(11) NOT NULL,
  `id_breed` int(11) NOT NULL,
  `id_stoodbook` int(11) NOT NULL,
  `is_abg` int(1) NOT NULL DEFAULT '0' COMMENT 'Членство в ABG',
  `date_born` timestamp NULL DEFAULT NULL COMMENT 'Дата рождения',
  `date_dead` timestamp NULL DEFAULT NULL COMMENT 'Дата смерти',
  `born_weight` int(11) DEFAULT NULL COMMENT 'Вес при рождении (г)',
  `born_qty` int(2) DEFAULT NULL COMMENT 'Родилась/родился в количестве',
  `manuf` varchar(64) DEFAULT NULL COMMENT 'Заводчик',
  `owner` varchar(64) DEFAULT NULL COMMENT 'Владелец',
  `ava` varchar(255) DEFAULT NULL,
  `score` float DEFAULT NULL COMMENT 'Оценочный балл',
  `code_ua` varchar(32) DEFAULT NULL COMMENT 'ID number UA',
  `code_abg` varchar(32) DEFAULT NULL COMMENT 'ID number ABG',
  `code_farm` varchar(32) DEFAULT NULL COMMENT 'ID по ФХ',
  `code_chip` varchar(32) DEFAULT NULL COMMENT 'ID чипа',
  `code_int` varchar(32) DEFAULT NULL COMMENT 'ID international',
  `cert_serial` varchar(255) DEFAULT NULL COMMENT 'Сертификат/Серия',
  `cert_no` varchar(255) DEFAULT NULL COMMENT 'Сертификат/Номер',
  `code_brand` varchar(255) DEFAULT NULL COMMENT 'Тавро/клеймо',
  `horns_type` int(1) DEFAULT NULL COMMENT 'Рогатость (0-комолый/1-обезрожен/2-рогатый)',
  `have_gen` int(1) NOT NULL DEFAULT '0' COMMENT 'Генетический паспорт (да/нет)',
  `gen_mat` text COMMENT 'Генетический материал животного',
  `source` text COMMENT 'Источник полученной информации',
  `special` text COMMENT 'Особые отметки',
  `id_lact_show` int(11) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=346 DEFAULT CHARSET=utf8;
