  `id_goat` int(11) NOT NULL,
  `viewer` varchar(64) NOT NULL COMMENT 'потомок/предок',
  `lact_no` int(11) DEFAULT NULL COMMENT 'Номер лактации',
  `lact_days` varchar(255) NOT NULL COMMENT 'дней лактаций',
