  `have_graph` int(1) NOT NULL DEFAULT '0' COMMENT 'График лактационной кривой',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=146 DEFAULT CHARSET=utf8 COMMENT='Данные по лактации (витрина)';
