DROP TABLE IF EXISTS `goats_milk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `goats_milk` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `id_goat` int(11) NOT NULL,
  `par_0` int(11) DEFAULT NULL COMMENT 'Номер лактации',
  `par_1` varchar(255) DEFAULT NULL COMMENT 'Кол-во дней лактации',
  `par_2` float DEFAULT NULL COMMENT 'Удой (кг)',
  `par_3` float DEFAULT NULL COMMENT 'Молочный жир (%)',
  `par_4` float DEFAULT NULL COMMENT 'Молочный белок (%)',
  `par_5` float DEFAULT NULL COMMENT 'Лактоза (%)',
  `par_6` float DEFAULT NULL COMMENT 'Суточный пиковый удой (кг)',
  `par_7` float DEFAULT NULL COMMENT 'Среднесуточный удой (кг)',
  `par_8` float DEFAULT NULL COMMENT 'Среднесуточный удой перед окончанием лактации (кг)',
  `par_9` float DEFAULT NULL COMMENT 'Скорость молокоотдачи (кг/мин)',
  `have_graph` int(1) NOT NULL DEFAULT '0' COMMENT 'График лактационной кривой',
  `source` text COMMENT 'Источник полученной информации',
  `time_added` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=165 DEFAULT CHARSET=utf8 COMMENT='Данные по лактации';
/*!40101 SET character_set_client = @saved_cs_client */;

